// Visita guiada 🎬 — mueve la CÁMARA sola alrededor del agente articulado que esté vivo.
//
// Por qué existe: el Mundo se juega con WASD + pointer lock, así que desde un móvil no hay forma de
// acercarse a un agente para verlo hacer nada. Esto no añade controles táctiles (eso es cosa del
// framework): sencillamente conduce la cámara por un guion durante ~25 segundos.
//
// Es AGNÓSTICO: orbita el primer esqueleto vivo, sea un zombie, una cabra o un boss.
// Toca la pantalla o pulsa una tecla para cortar y recuperar el control.

// ⚠️ Los avisos van por toast(), NO por console.warn: desde un móvil no hay consola que abrir, así
// que un console.warn es indistinguible de «el snippet no hace nada» — que es justo lo que parecía
// cuando faltaba el agente.
const aviso = m => { if (typeof toast === 'function') toast(m); console.warn(m); };
if (typeof mc === 'undefined' || !mc.pos || !mc.active) { aviso('🎬 Abre el Mundo antes de la visita.'); return; }
const vivos = ((typeof game !== 'undefined' && game.esqueletos && game.esqueletos._vivos) || [])
  .filter(r => r && !r.quitado);
if (!vivos.length) { aviso('🎬 No hay ningún agente vivo: ejecuta antes «Agente Zombie 🧟».'); return; }
const rig = vivos[0], R = rig.partes[0];

// Dónde está AHORA: el ancla no se mueve nunca, el desplazamiento vive en _sig.
const zx = () => rig.eje[0] + R.s._sig.x;
const zz = () => rig.eje[2] + R.s._sig.z;
const zpies = () => rig.cuerpo[1] + R.s._sig.y;
const MC_EYE = 1.62;                       // app.js: mc.pos son los PIES; el ojo va 1,62 más arriba

// El guion toca la detección del agente para la primera toma: parado a 3 bloques no se puede ver de
// otra forma, porque te persigue en cuanto entras en sus 14. Se restaura en la toma siguiente.
const DETECCION = rig.G.deteccion;
// ⚠️ Los cortes se arman DESPUÉS, al arrancar el guion de verdad: cerrar el panel de snippets es un
// toque, y armarlos aquí haría que la visita se cancelara justo al empezar.
let cortada = false;
const cortar = () => { cortada = true; };
const armarCortes = () => { addEventListener('pointerdown', cortar, { once: true });
                            addEventListener('keydown', cortar, { once: true }); };

// Cámara: siempre mirando al agente desde un ángulo y una distancia. yaw = ángulo (app.js: yaw 0
// mira hacia -Z, así que colocarse en +Z y poner yaw = ángulo deja al bicho justo en el centro).
function mirarDesde(ang, dist, alto) {
  mc.pos[0] = zx() + Math.sin(ang) * dist;
  mc.pos[2] = zz() + Math.cos(ang) * dist;
  mc.pos[1] = zpies() + alto - MC_EYE;
  mc.yaw = ang; mc.pitch = 0;
  mc.vel[0] = mc.vel[1] = mc.vel[2] = 0;   // sin esto la física acumula caída y da tirones
}

// ⚠️ El reloj NO arranca con el ▶. El panel de snippets tapa el Mundo entero, así que si el guion
// empezase aquí, media visita pasaría detrás del panel y al cerrarlo ya no quedaría nada que ver.
// Arranca cuando el panel se cierra, y hasta entonces solo espera.
let t0 = 0, ang0 = 0, huida = null;
const panel = document.querySelector('#snip-modal');
aviso('🎬 Cierra este panel y empieza la visita (~28 s).');

function paso() {
  if (cortada) { rig.G.deteccion = DETECCION; aviso('🎬 Visita cortada.'); return; }
  if (!t0) {                                  // aún con el panel abierto: esperar sin gastar guion
    if (panel && !panel.hidden) return requestAnimationFrame(paso);
    t0 = performance.now();
    setTimeout(armarCortes, 400);             // 400 ms de gracia: el toque que cerró el panel no cuenta
    aviso('🎬 Visita guiada. Toca la pantalla para cortar.');
  }
  const t = (performance.now() - t0) / 1000;

  if (t < 7) {
    // 1) PARADO. ⚠️ NO se pone a 0: en la librería `deteccion: 0` es «sin límite, persigue siempre»
    // (pasoSeguir: `G.deteccion > 0 && d > G.deteccion`). Un radio ridículo es lo que lo deja quieto.
    rig.G.deteccion = 0.01;
    mirarDesde(t * 0.8, 3.4, 1.3);
    ang0 = t * 0.8;
  } else if (t < 11) {
    // 2) TE VE. Vuelve su detección: gira hacia ti, levanta los brazos y arranca.
    rig.G.deteccion = DETECCION;
    mirarDesde(ang0, 3.4, 1.3);
  } else if (t < 18) {
    // 3) LA PERSECUCIÓN. La cámara retrocede mirándole de frente: así se le ve andar de verdad, con
    // su ciclo de piernas, que es lo que no se aprecia estando quieto.
    // ⚠️ Un pelo MÁS DESPACIO que él (2,15 contra 2,2). Huyendo más rápido se sale de sus 14 de
    // detección, y entonces hace lo correcto y lo peor para una demo: darse la vuelta y volverse a
    // su sitio. Yendo más lento no lo pierde nunca y camina la toma entera.
    if (!huida) huida = { x: mc.pos[0], z: mc.pos[2], a: ang0 };
    const d = (t - 11) * 2.15;
    mc.pos[0] = huida.x + Math.sin(huida.a) * d;
    mc.pos[2] = huida.z + Math.cos(huida.a) * d;
    mc.pos[1] = zpies() + 1.3 - MC_EYE;
    mc.yaw = huida.a; mc.pitch = 0;
    mc.vel[0] = mc.vel[1] = mc.vel[2] = 0;
  } else if (t < 22) {
    // 4) TE ALCANZA. La cámara se para: cierra hasta su `distancia` y se queda encima.
    mc.pos[1] = zpies() + 1.3 - MC_EYE;
    mc.vel[0] = mc.vel[1] = mc.vel[2] = 0;
  } else if (t < 28) {
    // 5) DE CERCA. Órbita a 2 bloques: el cuerpo gira para seguirte y la CABEZA corrige lo que le
    // falta al cuerpo (por eso no se le queda la cara torcida).
    mirarDesde(huida.a + (t - 22) * 0.9, 2.0, 1.5);
  } else {
    rig.G.deteccion = DETECCION;
    console.log('🎬 fin. game.esqueletos.lista() · game.esqueletos.quitar() para retirarlo.');
    return;
  }
  requestAnimationFrame(paso);
}
requestAnimationFrame(paso);
